"use client";

import { useStore } from "@/lib/store";
import { useState, useEffect } from "react";
import { format, parse } from "date-fns";
import { CheckCircle2, ChevronLeft, ChevronRight, Circle, Palmtree, ShieldAlert } from "lucide-react";

// Helpers for bidirectional time format conversion
const to24Hour = (time12h: string) => {
  if (!time12h) return "";
  const d = parse(time12h, 'hh:mm a', new Date());
  return format(d, 'HH:mm');
};

const to12Hour = (time24h: string) => {
  if (!time24h) return "";
  const d = parse(time24h, 'HH:mm', new Date());
  return format(d, 'hh:mm a');
};

export default function AttendancePage() {
  const [mounted, setMounted] = useState(false);
  const { employees, attendance, leaves, markAttendance } = useStore();
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  useEffect(() => setMounted(true), []);

  if (!mounted) return null;

  const dateStr = format(selectedDate, 'yyyy-MM-dd');
  const getCurrentTime12Hour = () => format(new Date(), 'hh:mm a');

  const handleQuickMark = (employeeId: string, type: 'checkIn' | 'checkOut') => {
    markAttendance(employeeId, dateStr, type, getCurrentTime12Hour());
  };

  const handleManualSelect = (employeeId: string, type: 'checkIn' | 'checkOut', val24h: string) => {
    if(!val24h) return;
    markAttendance(employeeId, dateStr, type, to12Hour(val24h));
  };

  const handleUncheck = (employeeId: string, type: 'checkIn' | 'checkOut') => {
    markAttendance(employeeId, dateStr, type, "");
  };

  const nextDay = () => {
    const d = new Date(selectedDate); d.setDate(d.getDate() + 1); setSelectedDate(d);
  };
  const prevDay = () => {
    const d = new Date(selectedDate); d.setDate(d.getDate() - 1); setSelectedDate(d);
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto pb-10">
      <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900">Attendance Log</h1>
          <p className="text-slate-500 mt-1 text-base">Daily registry for personnel presence and session tracking.</p>
        </div>
        
        <div className="flex items-center gap-4 bg-white border border-slate-200 p-1.5 rounded-xl shadow-sm">
          <button onClick={prevDay} className="p-2 hover:bg-slate-100 transition-all rounded-lg text-slate-400 hover:text-slate-900">
            <ChevronLeft size={18} strokeWidth={2.5}/>
          </button>
          <div className="font-semibold text-slate-700 min-w-[140px] text-center text-xs">
            {format(selectedDate, 'MMM dd, yyyy')}
          </div>
          <button onClick={nextDay} className="p-2 hover:bg-slate-100 transition-all rounded-lg text-slate-400 hover:text-slate-900">
            <ChevronRight size={18} strokeWidth={2.5}/>
          </button>
        </div>
      </header>

      {employees.length === 0 ? (
        <div className="bg-white p-20 text-center rounded-2xl border border-slate-200 text-slate-400 text-sm font-medium">
          No personnel records found in the database.
        </div>
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          {/* Desktop Table View */}
          <div className="hidden lg:block overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 text-slate-400 text-[11px] font-bold uppercase tracking-wider border-b border-slate-200">
                  <th className="px-8 py-5">Employee</th>
                  <th className="px-8 py-5">Status</th>
                  <th className="px-8 py-5">Check In</th>
                  <th className="px-8 py-5">Check Out</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {employees.map((emp) => {
                  const record = attendance.find(a => a.employeeId === emp.id && a.date === dateStr);
                  const isPresent = !!record?.checkIn;
                  const currentLeave = leaves.find(l => {
                    if (l.employeeId !== emp.id) return false;
                    const start = l.startDate || (l as any).date;
                    const end = l.endDate || (l as any).date;
                    return dateStr >= start && dateStr <= end; 
                  });
                  
                  return (
                    <tr key={emp.id} className={`transition-all duration-200 ${currentLeave ? 'bg-rose-50/30' : 'hover:bg-slate-50 group'}`}>
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-4">
                          <div className={`w-11 h-11 border-2 transition-colors flex items-center justify-center font-bold text-sm flex-shrink-0 rounded-full overflow-hidden ${currentLeave ? 'bg-rose-100 border-white text-rose-600 shadow-sm' : 'bg-slate-100 border-white text-slate-500'}`}>
                            {emp.photoUrl ? <img src={emp.photoUrl} alt="" className="w-full h-full object-cover"/> : emp.name.charAt(0)}
                          </div>
                          <span className={`font-semibold text-sm tracking-tight ${currentLeave ? 'text-rose-700' : 'text-slate-700'}`}>{emp.name}</span>
                        </div>
                      </td>
                      
                      <td className="px-8 py-6">
                        {currentLeave ? (
                          <span className="inline-flex items-center gap-2 px-3 py-1.5 bg-rose-100 text-rose-700 text-[10px] font-bold uppercase tracking-wider rounded-lg">
                            {currentLeave.type === 'Annual' ? <Palmtree size={12} strokeWidth={3}/> : <ShieldAlert size={12} strokeWidth={3}/>} 
                            ON LEAVE
                          </span>
                        ) : isPresent ? (
                          <span className="inline-flex items-center gap-2 px-3 py-1.5 bg-emerald-100 text-emerald-700 text-[10px] font-bold uppercase tracking-wider rounded-lg">
                            <CheckCircle2 size={12} strokeWidth={3} /> Present
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-2 px-3 py-1.5 bg-slate-100 text-slate-400 text-[10px] font-bold uppercase tracking-wider rounded-lg">
                            <Circle size={12} strokeWidth={3} /> Pending
                          </span>
                        )}
                      </td>

                      {currentLeave ? (
                        <td colSpan={2} className="px-8 py-6 text-sm font-medium text-rose-400 italic opacity-60 text-center">
                           Leave protocol active
                        </td>
                      ) : (
                        <>
                          <td className="px-8 py-6">
                            {record?.checkIn ? (
                              <div className="flex items-center gap-4">
                                <span className="font-bold text-lg text-slate-900 border-b-2 border-teal-200 pb-0.5 tabular-nums">{record.checkIn}</span>
                                <div className="flex gap-2">
                                  <input 
                                    type="time"
                                    className="text-[11px] font-bold text-slate-400 outline-none bg-slate-50 border border-slate-200 px-2 py-1 rounded-md focus:border-teal-400 transition-all lg:opacity-0 group-hover:opacity-100"
                                    onChange={(e) => handleManualSelect(emp.id, 'checkIn', e.target.value)}
                                    value={to24Hour(record.checkIn || "")}
                                  />
                                  <button
                                    onClick={() => handleUncheck(emp.id, 'checkIn')}
                                    className="text-[11px] font-bold text-rose-500 outline-none bg-rose-50 border border-rose-200 px-2 py-1 rounded-md hover:bg-rose-100 transition-all lg:opacity-0 group-hover:opacity-100"
                                  >
                                    Undo
                                  </button>
                                </div>
                              </div>
                            ) : (
                              <div className="flex items-center gap-3">
                                <button 
                                  onClick={() => handleQuickMark(emp.id, 'checkIn')}
                                  className="bg-teal-600 hover:bg-teal-700 text-white px-5 py-2 text-[11px] font-bold rounded-lg transition-all shadow-sm"
                                >
                                  Check In
                                </button>
                                <input 
                                  type="time"
                                  className="bg-white border border-slate-200 px-3 py-2 text-[11px] font-semibold text-slate-600 outline-none focus:border-teal-400 transition-all rounded-lg w-32"
                                  onChange={(e) => handleManualSelect(emp.id, 'checkIn', e.target.value)}
                                  value={""}
                                />
                              </div>
                            )}
                          </td>
                          <td className="px-8 py-6">
                            {record?.checkOut ? (
                              <div className="flex items-center gap-4">
                                <span className="font-bold text-lg text-slate-900 border-b-2 border-teal-200 pb-0.5 tabular-nums">{record.checkOut}</span>
                                <div className="flex gap-2">
                                  <input 
                                    type="time"
                                    className="text-[11px] font-bold text-slate-400 outline-none bg-slate-50 border border-slate-200 px-2 py-1 rounded-md focus:border-teal-400 transition-all lg:opacity-0 group-hover:opacity-100"
                                    onChange={(e) => handleManualSelect(emp.id, 'checkOut', e.target.value)}
                                    value={to24Hour(record.checkOut || "")}
                                  />
                                  <button
                                    onClick={() => handleUncheck(emp.id, 'checkOut')}
                                    className="text-[11px] font-bold text-rose-500 outline-none bg-rose-50 border border-rose-200 px-2 py-1 rounded-md hover:bg-rose-100 transition-all lg:opacity-0 group-hover:opacity-100"
                                  >
                                    Undo
                                  </button>
                                </div>
                              </div>
                            ) : (
                              <div className="flex items-center gap-3">
                                <button 
                                  onClick={() => handleQuickMark(emp.id, 'checkOut')}
                                  disabled={!record?.checkIn}
                                  className={`px-5 py-2 text-[11px] font-bold rounded-lg transition-all shadow-sm ${record?.checkIn ? 'bg-white border border-slate-200 text-slate-700 hover:bg-slate-50' : 'bg-slate-50 border border-slate-100 text-slate-300 cursor-not-allowed'}`}
                                >
                                  Check Out
                                </button>
                                <input 
                                  type="time"
                                  className="bg-white border border-slate-200 px-3 py-2 text-[11px] font-semibold text-slate-600 outline-none focus:border-teal-400 transition-all rounded-lg w-32 disabled:opacity-50"
                                  onChange={(e) => handleManualSelect(emp.id, 'checkOut', e.target.value)}
                                  disabled={!record?.checkIn}
                                  value={""}
                                />
                              </div>
                            )}
                          </td>
                        </>
                      )}
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>

          {/* Mobile Card View */}
          <div className="lg:hidden divide-y divide-slate-100">
            {employees.map((emp) => {
              const record = attendance.find(a => a.employeeId === emp.id && a.date === dateStr);
              const isPresent = !!record?.checkIn;
              const currentLeave = leaves.find(l => {
                if (l.employeeId !== emp.id) return false;
                const start = l.startDate || (l as any).date;
                const end = l.endDate || (l as any).date;
                return dateStr >= start && dateStr <= end; 
              });

              return (
                <div key={emp.id} className={`p-5 space-y-5 transition-all ${currentLeave ? 'bg-rose-50/30' : 'bg-white'}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 border-2 rounded-full overflow-hidden flex items-center justify-center font-bold text-xs shrink-0 ${currentLeave ? 'bg-rose-100 border-white text-rose-600' : 'bg-slate-100 border-white text-slate-500'}`}>
                        {emp.photoUrl ? <img src={emp.photoUrl} alt="" className="w-full h-full object-cover"/> : emp.name.charAt(0)}
                      </div>
                      <div>
                        <h3 className={`font-bold text-sm tracking-tight ${currentLeave ? 'text-rose-700' : 'text-slate-800'}`}>{emp.name}</h3>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">ID: {emp.id.slice(0, 8)}</p>
                      </div>
                    </div>
                    {currentLeave ? (
                      <span className="px-3 py-1 bg-rose-100 text-rose-700 text-[9px] font-bold uppercase tracking-wider rounded-lg flex items-center gap-1.5">
                        <ShieldAlert size={10} /> LEAVE
                      </span>
                    ) : isPresent ? (
                      <span className="px-3 py-1 bg-emerald-100 text-emerald-700 text-[9px] font-bold uppercase tracking-wider rounded-lg flex items-center gap-1.5">
                        <CheckCircle2 size={10} /> PRESENT
                      </span>
                    ) : (
                      <span className="px-3 py-1 bg-slate-100 text-slate-400 text-[9px] font-bold uppercase tracking-wider rounded-lg flex items-center gap-1.5">
                        <Circle size={10} /> PENDING
                      </span>
                    )}
                  </div>

                  {!currentLeave && (
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Check In</p>
                        {record?.checkIn ? (
                          <div className="flex flex-col gap-2">
                            <span className="font-extrabold text-lg text-slate-900 tabular-nums">{record.checkIn}</span>
                            <button
                              onClick={() => handleUncheck(emp.id, 'checkIn')}
                              className="w-full py-2 text-[10px] font-bold text-rose-500 bg-rose-50 border border-rose-100 rounded-lg"
                            >
                              Reset
                            </button>
                          </div>
                        ) : (
                          <div className="flex flex-col gap-2">
                            <button 
                              onClick={() => handleQuickMark(emp.id, 'checkIn')}
                              className="w-full bg-teal-600 text-white py-3 rounded-xl text-[11px] font-bold shadow-lg shadow-teal-600/10"
                            >
                              Mark In
                            </button>
                            <input 
                              type="time"
                              className="w-full bg-slate-50 border border-slate-200 px-3 py-2 rounded-lg text-[11px] font-semibold text-slate-600"
                              onChange={(e) => handleManualSelect(emp.id, 'checkIn', e.target.value)}
                            />
                          </div>
                        )}
                      </div>

                      <div className="space-y-2">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Check Out</p>
                        {record?.checkOut ? (
                          <div className="flex flex-col gap-2">
                            <span className="font-extrabold text-lg text-slate-900 tabular-nums">{record.checkOut}</span>
                            <button
                              onClick={() => handleUncheck(emp.id, 'checkOut')}
                              className="w-full py-2 text-[10px] font-bold text-rose-500 bg-rose-50 border border-rose-100 rounded-lg"
                            >
                              Reset
                            </button>
                          </div>
                        ) : (
                          <div className="flex flex-col gap-2">
                            <button 
                              onClick={() => handleQuickMark(emp.id, 'checkOut')}
                              disabled={!record?.checkIn}
                              className={`w-full py-3 rounded-xl text-[11px] font-bold shadow-lg ${record?.checkIn ? 'bg-white border border-slate-200 text-slate-800 shadow-slate-200/50' : 'bg-slate-50 border border-slate-100 text-slate-300 shadow-none'}`}
                            >
                              Mark Out
                            </button>
                            <input 
                              type="time"
                              disabled={!record?.checkIn}
                              className="w-full bg-slate-50 border border-slate-200 px-3 py-2 rounded-lg text-[11px] font-semibold text-slate-600 disabled:opacity-50"
                              onChange={(e) => handleManualSelect(emp.id, 'checkOut', e.target.value)}
                            />
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import { useState, useEffect } from "react";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isToday, isSameDay, isWithinInterval, parseISO } from "date-fns";
import { isBusinessDay } from "@/lib/dateUtils";
import { ChevronLeft, ChevronRight, UserCheck, CalendarOff, ShieldAlert, CircleDashed } from "lucide-react";

export default function CalendarPage() {
  const [mounted, setMounted] = useState(false);
  const { employees, attendance, leaves } = useStore();
  
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());

  useEffect(() => setMounted(true), []);

  if (!mounted) return null;

  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const daysInMonth = eachDayOfInterval({ start: monthStart, end: monthEnd });

  const dateStr = format(selectedDate, 'yyyy-MM-dd');
  
  const isLeaveActive = (l: any, targetDateStr: string) => {
    if (!isBusinessDay(parseISO(targetDateStr))) return false;
    const start = l.startDate || l.date;
    const end = l.endDate || start;
    if (!start) return false;
    try {
      return isWithinInterval(parseISO(targetDateStr), { start: parseISO(start), end: parseISO(end) });
    } catch {
      return false;
    }
  };

  // Details for selected Date
  const attendedToday = attendance.filter(a => a.date === dateStr && a.checkIn).map(a => ({
    record: a,
    emp: employees.find(e => e.id === a.employeeId)
  })).filter(x => x.emp);

  const leavesToday = leaves.filter(l => isLeaveActive(l, dateStr)).map(l => ({
    record: l,
    emp: employees.find(e => e.id === l.employeeId)
  })).filter(x => x.emp);

  const annualLeaves = leavesToday.filter(l => l.record.type === 'Annual');
  const sickLeaves = leavesToday.filter(l => l.record.type === 'Sick/Emergency');

  return (
    <div className="space-y-6 lg:space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto lg:h-[calc(100vh-100px)] flex flex-col pb-6 lg:overflow-hidden">
      <header className="shrink-0 mb-2">
        <h1 className="text-2xl sm:text-3xl font-bold tracking-tight text-slate-900">Attendance Matrix</h1>
        <p className="text-slate-500 mt-1 text-sm sm:text-base">Comprehensive view of workforce distribution and attendance patterns.</p>
      </header>

      <div className="flex-1 flex flex-col lg:flex-row gap-6 lg:gap-8 min-h-0">
        
        {/* Left Pane: Calendar Grid */}
        <div className="w-full lg:w-3/5 xl:w-[65%] bg-white border border-slate-200 rounded-3xl shadow-sm flex flex-col overflow-hidden">
          <div className="p-4 sm:p-6 lg:p-8 border-b border-slate-50 flex flex-col sm:flex-row items-start sm:items-center justify-between shrink-0 bg-slate-50/30 gap-4 sm:gap-0">
            <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest hidden sm:block">Monthly Overview</h2>
            <div className="flex items-center gap-2 sm:gap-4 bg-white border border-slate-200 p-1.5 rounded-xl shadow-sm w-full sm:w-auto justify-between sm:justify-start">
               <button 
                  onClick={() => { const d = new Date(currentMonth); d.setMonth(d.getMonth() - 1); setCurrentMonth(d); }}
                  className="p-2 hover:bg-slate-50 transition-all rounded-lg text-slate-400 hover:text-slate-900 focus:outline-none"
                >
                 <ChevronLeft size={20} strokeWidth={2.5} />
               </button>
               <span className="font-bold uppercase tracking-wider text-[11px] text-slate-700 min-w-[120px] text-center">
                 {format(currentMonth, 'MMMM yyyy')}
               </span>
               <button 
                  onClick={() => { const d = new Date(currentMonth); d.setMonth(d.getMonth() + 1); setCurrentMonth(d); }}
                  className="p-2 hover:bg-slate-50 transition-all rounded-lg text-slate-400 hover:text-slate-900 focus:outline-none"
                >
                 <ChevronRight size={20} strokeWidth={2.5} />
               </button>
            </div>
          </div>

          <div className="p-4 sm:p-6 lg:p-8 flex-1 overflow-y-auto bg-white relative">
            <div className="grid grid-cols-7 gap-1 sm:gap-3 mb-4 sm:mb-6">
              {['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d => (
                <div key={d} className="text-center text-[10px] font-bold uppercase tracking-widest text-slate-300 py-2 border-b border-slate-50">{d}</div>
              ))}
            </div>
            
            <div className="grid grid-cols-7 gap-1 sm:gap-3">
               {Array.from({ length: monthStart.getDay() }).map((_, i) => (
                <div key={`empty-${i}`} className="h-16 sm:h-24 lg:h-28 rounded-lg sm:rounded-xl bg-slate-50/50 border border-slate-50 opacity-40" />
              ))}
              
              {daysInMonth.map((day) => {
                const dayStr = format(day, 'yyyy-MM-dd');
                const _isToday = isToday(day);
                const _isSelected = isSameDay(day, selectedDate);
                
                const hasAttendance = attendance.some(a => a.date === dayStr && a.checkIn);
                const hasAnnualLeave = leaves.some(l => l.type === 'Annual' && isLeaveActive(l, dayStr));
                const hasSickLeave = leaves.some(l => l.type === 'Sick/Emergency' && isLeaveActive(l, dayStr));

                return (
                  <button 
                    key={dayStr}
                    onClick={() => setSelectedDate(day)}
                    className={`h-16 sm:h-24 lg:h-28 rounded-lg sm:rounded-xl border p-1.5 sm:p-3 flex flex-col relative transition-all focus:outline-none group ${
                      _isSelected 
                        ? 'bg-teal-50 border-teal-600 shadow-md shadow-teal-50 z-10' 
                        : _isToday 
                          ? 'bg-white border-teal-200' 
                          : 'bg-white border-slate-100 hover:border-slate-200'
                    }`}
                  >
                    <div className="flex justify-between items-start mb-auto w-full">
                      <span className={`text-[10px] sm:text-[11px] font-bold flex items-center justify-center w-5 h-5 sm:w-7 sm:h-7 rounded-md sm:rounded-lg transition-all mx-auto sm:mx-0 ${
                        _isSelected ? 'bg-teal-600 text-white' : _isToday ? 'bg-teal-50 text-teal-600' : 'text-slate-500 sm:text-slate-300'
                      }`}>
                        {format(day, 'd')}
                      </span>
                    </div>
                    
                    <div className="flex items-center gap-0.5 sm:gap-1.5 justify-center sm:justify-end w-full mt-1 sm:mt-0">
                      {hasAttendance && <div className="w-1 h-1 sm:w-1.5 sm:h-1.5 rounded-full bg-teal-500" title="Present" />}
                      {hasAnnualLeave && <div className="w-1 h-1 sm:w-1.5 sm:h-1.5 rounded-full bg-amber-400" title="Annual Leave" />}
                      {hasSickLeave && <div className="w-1 h-1 sm:w-1.5 sm:h-1.5 rounded-full bg-rose-400" title="Sick Leave" />}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Right Pane: Daily Summary */}
        <div className="w-full lg:w-2/5 xl:w-[35%] bg-white border border-slate-200 rounded-3xl shadow-sm flex flex-col min-h-[400px]">
          <div className="p-6 lg:p-8 border-b border-slate-50 bg-slate-50/30">
            <h2 className="text-[11px] font-bold uppercase tracking-widest text-slate-400 mb-2">Daily Summary</h2>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 tracking-tight">{format(selectedDate, 'EEEE, MMM do')}</p>
          </div>

          <div className="p-6 lg:p-8 flex-1 overflow-y-auto space-y-8 lg:space-y-10 bg-white">
            
            {/* Presence */}
            <section className="space-y-5">
              <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center justify-between border-b border-slate-50 pb-3">
                <span className="flex items-center gap-2"><UserCheck size={16} strokeWidth={2.5} className="text-teal-600" /> Present</span>
                <span className="bg-slate-50 px-2 py-0.5 rounded-md text-slate-500 text-[10px] tabular-nums font-bold">{attendedToday.length}</span>
              </h3>
              {attendedToday.length === 0 ? (
                <p className="text-center py-6 text-slate-300 text-xs font-semibold">No attendance recorded.</p>
              ) : (
                <div className="space-y-3">
                  {attendedToday.map(({ emp, record }) => (
                    <div key={emp!.id} className="flex items-center justify-between p-4 bg-slate-50/50 border border-slate-100 rounded-xl group hover:border-teal-200 transition-colors">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full shrink-0 bg-white border border-slate-200 text-slate-300 font-bold text-sm flex items-center justify-center transition-transform group-hover:scale-105">
                          {emp!.photoUrl ? <img src={emp!.photoUrl} alt="" className="w-full h-full object-cover rounded-full" /> : emp!.name.charAt(0)}
                        </div>
                        <div>
                          <span className="font-bold text-sm text-slate-800 tracking-tight block uppercase">{emp!.name}</span>
                          <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">{emp!.id.slice(0,8)}</span>
                        </div>
                      </div>
                      <div className="text-right flex flex-col items-end">
                        <span className="text-[11px] font-bold text-teal-600 tabular-nums">{record.checkIn}</span>
                        {record.checkOut && <span className="text-[9px] font-bold text-slate-400 tabular-nums uppercase opacity-50 mt-0.5">{record.checkOut}</span>}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>

            {/* Annual Leave */}
            <section className="space-y-5">
              <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center justify-between border-b border-slate-50 pb-3">
                <span className="flex items-center gap-2"><CircleDashed size={16} strokeWidth={2.5} className="text-amber-500" /> Annual Leave</span>
                <span className="bg-slate-50 px-2 py-0.5 rounded-md text-slate-500 text-[10px] tabular-nums font-bold">{annualLeaves.length}</span>
              </h3>
              {annualLeaves.length === 0 ? (
                 <p className="text-center py-6 text-slate-200 text-xs font-semibold">No annual leaves.</p>
              ) : (
                <div className="space-y-3">
                  {annualLeaves.map(({ emp }) => (
                    <div key={emp!.id} className="flex items-center gap-3 p-3 bg-white border border-amber-100 rounded-xl">
                      <div className="w-8 h-8 rounded-full shrink-0 bg-amber-50 text-amber-600 font-bold text-xs flex items-center justify-center">
                        {emp!.photoUrl ? <img src={emp!.photoUrl} alt="" className="w-full h-full object-cover rounded-full" /> : emp!.name.charAt(0)}
                      </div>
                      <span className="font-bold text-xs text-slate-700 tracking-tight uppercase">{emp!.name}</span>
                    </div>
                  ))}
                </div>
              )}
            </section>

            {/* Sick Leave */}
            <section className="space-y-5">
              <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center justify-between border-b border-slate-50 pb-3">
                <span className="flex items-center gap-2"><ShieldAlert size={16} strokeWidth={2.5} className="text-rose-500" /> Sick Leave</span>
                <span className="bg-slate-50 px-2 py-0.5 rounded-md text-slate-500 text-[10px] tabular-nums font-bold">{sickLeaves.length}</span>
              </h3>
              {sickLeaves.length === 0 ? (
                 <p className="text-center py-6 text-slate-200 text-xs font-semibold">No sick leaves.</p>
              ) : (
                <div className="space-y-3">
                  {sickLeaves.map(({ emp }) => (
                    <div key={emp!.id} className="flex items-center gap-3 p-3 bg-white border border-slate-100 rounded-xl">
                      <div className="w-8 h-8 rounded-full shrink-0 bg-slate-50 text-slate-400 font-bold text-xs flex items-center justify-center">
                        {emp!.photoUrl ? <img src={emp!.photoUrl} alt="" className="w-full h-full object-cover rounded-full" /> : emp!.name.charAt(0)}
                      </div>
                      <span className="font-bold text-xs text-slate-700 tracking-tight uppercase">{emp!.name}</span>
                    </div>
                  ))}
                </div>
              )}
            </section>

          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isToday } from "date-fns";
import { isBusinessDay, ANNUAL_LEAVE_LIMIT } from "@/lib/dateUtils";
import { ArrowLeft, CalendarOff, UserCheck, ShieldAlert, BadgeInfo, BarChart3, Clock, Download, Table } from "lucide-react";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import * as XLSX from "xlsx";
import Link from "next/link";

export default function EmployeeProfilePage() {
  const { id } = useParams() as { id: string };
  const { employees, attendance, leaves } = useStore();
  const [mounted, setMounted] = useState(false);
  
  const [currentMonth, setCurrentMonth] = useState(new Date());

  useEffect(() => setMounted(true), []);

  if (!mounted) return null;

  const employee = employees.find((e) => e.id === id);

  if (!employee) {
    return (
      <div className="p-32 text-center bg-white border border-slate-200 rounded-3xl shadow-sm mt-10">
        <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Employee Not Found</h2>
        <p className="text-slate-500 mt-2 mb-8">The requested profile does not exist in the database.</p>
        <Link href="/employees" className="inline-block px-8 py-3 bg-teal-600 text-white font-bold text-sm rounded-xl hover:bg-teal-700 transition-all shadow-md shadow-teal-100">
          Back to Directory
        </Link>
      </div>
    );
  }

  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const daysInMonth = eachDayOfInterval({ start: monthStart, end: monthEnd });

  // Monthly stats
  const monthlyAttendance = attendance.filter(a => a.employeeId === id && isSameMonth(new Date(a.date), currentMonth) && a.checkIn);
  
  // All Time Stats
  const allTimeLeaves = leaves.filter(l => l.employeeId === id).map(l => ({
    ...l,
    startDate: l.startDate || (l as any).date || new Date().toISOString(),
    endDate: l.endDate || (l as any).date || new Date().toISOString()
  }));

  let totalAnnual = 0;
  let totalSick = 0;
  allTimeLeaves.forEach(l => {
    const start = new Date(l.startDate);
    const end = new Date(l.endDate);
    try {
      const days = eachDayOfInterval({ start, end });
      days.forEach(d => {
        if (isBusinessDay(d)) {
          if (l.type === 'Annual') totalAnnual += 1;
          else totalSick += 1;
        }
      });
    } catch (e) {
      // Fallback
    }
  });

  const generateExcel = () => {
    const records: any[] = [];
    const empAtts = attendance.filter(a => a.employeeId === id && a.checkIn);
    empAtts.forEach(a => records.push({ Date: a.date, Type: 'Attendance', Details: `IN: ${a.checkIn} ${a.checkOut ? `OUT: ${a.checkOut}` : ''}` }));
    
    allTimeLeaves.forEach(l => {
      const start = new Date(l.startDate);
      const end = new Date(l.endDate);
      eachDayOfInterval({ start, end }).forEach(d => {
        if (isBusinessDay(d)) {
          records.push({ Date: format(d, 'yyyy-MM-dd'), Type: l.type + ' Leave', Details: 'Full Day' });
        }
      });
    });

    records.sort((a,b) => new Date(a.Date).getTime() - new Date(b.Date).getTime());

    const wb = XLSX.utils.book_new();
    const sumData = [
      [`Elevate Ventures - ${employee.name} Profile`],
      ['Total Active Days', empAtts.length.toString()],
      ['Total Annual Leave', totalAnnual.toString()],
      ['Remaining Annual Leave', (ANNUAL_LEAVE_LIMIT - totalAnnual).toString()],
      ['Total Sick Leave', totalSick.toString()],
    ];
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(sumData), "Profile Summary");

    const detailsData = [['Date', 'Type', 'Details']];
    records.forEach(r => detailsData.push([r.Date, r.Type, r.Details]));
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(detailsData), "Detailed Logs");

    XLSX.writeFile(wb, `Profile_${employee.name.replace(/\s+/g, '_')}.xlsx`);
  };

  const generatePDF = async () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.width;
    doc.setFillColor(13, 148, 136);
    doc.rect(0, 0, pageWidth, 40, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text(`PROFILE: ${employee.name.toUpperCase()}`, 15, 25);
    
    let currentY = 55;
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(14);
    doc.text("PERFORMANCE SUMMARY", 15, currentY);
    
    currentY += 10;
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    
    const empAtts = attendance.filter(a => a.employeeId === id && a.checkIn);
    doc.text(`Active Days: ${empAtts.length}`, 15, currentY); currentY += 6;
    doc.text(`Annual Leaves Taken: ${totalAnnual} / ${ANNUAL_LEAVE_LIMIT} (Remaining: ${ANNUAL_LEAVE_LIMIT - totalAnnual})`, 15, currentY); currentY += 6;
    doc.text(`Sick Leaves: ${totalSick}`, 15, currentY); currentY += 15;

    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text("ACTIVITY LOGS", 15, currentY);

    const records: any[] = [];
    empAtts.forEach(a => records.push([a.date, 'Attendance', `IN: ${a.checkIn} ${a.checkOut ? `OUT: ${a.checkOut}` : ''}` ]));
    
    allTimeLeaves.forEach(l => {
      const start = new Date(l.startDate);
      const end = new Date(l.endDate);
      eachDayOfInterval({ start, end }).forEach(d => {
        if (isBusinessDay(d)) {
          records.push([format(d, 'yyyy-MM-dd'), l.type + ' Leave', 'Full Day']);
        }
      });
    });

    records.sort((a,b) => new Date(a[0]).getTime() - new Date(b[0]).getTime());

    autoTable(doc, {
      startY: currentY + 5,
      head: [['DATE', 'TYPE', 'DETAILS']],
      body: records,
      theme: 'grid',
      headStyles: { fillColor: [241, 245, 249], textColor: [71, 85, 105], fontStyle: 'bold', lineWidth: 0.1, lineColor: [226, 232, 240] },
      styles: { font: 'helvetica', fontSize: 8, textColor: [51, 65, 85], cellPadding: 3 },
      alternateRowStyles: { fillColor: [252, 253, 254] }
    });

    doc.save(`Profile_${employee.name.replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto pb-10">
      
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-6">
          <Link href="/employees" className="w-10 h-10 rounded-xl bg-white border border-slate-200 flex items-center justify-center text-slate-400 hover:text-teal-600 hover:border-teal-200 transition-all shadow-sm group">
            <ArrowLeft size={20} strokeWidth={2.5} className="transition-transform group-hover:-translate-x-0.5" />
          </Link>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900">Employee Profile</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={generateExcel} className="hidden sm:flex px-4 py-2 bg-white border border-slate-200 text-slate-600 hover:text-teal-600 hover:border-teal-200 rounded-xl items-center justify-center gap-2 transition-all shadow-sm font-bold text-xs uppercase tracking-wider group" title="Export Excel">
            <Table size={16} strokeWidth={2.5} /> Excel
          </button>
          <button onClick={generatePDF} className="flex px-4 py-2 bg-teal-600 text-white hover:bg-teal-700 rounded-xl items-center justify-center gap-2 transition-all shadow-md shadow-teal-100 font-bold text-xs uppercase tracking-wider" title="Export PDF">
            <Download size={16} strokeWidth={2.5} /> PDF
          </button>
        </div>
      </div>

      {/* Profile Header */}
      <div className="bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden relative">
        <div className="h-32 bg-slate-50 border-b border-slate-100" />
        <div className="relative px-10 pb-10 flex flex-col md:flex-row gap-8 md:items-end -mt-16">
          <div className="w-40 h-40 rounded-full border-4 border-white shadow-md bg-slate-100 flex-shrink-0 overflow-hidden flex items-center justify-center text-slate-300 font-bold text-5xl">
            {employee.photoUrl ? (
              <img src={employee.photoUrl} alt={employee.name} className="w-full h-full object-cover" />
            ) : (
              <span className="uppercase">{employee.name.charAt(0)}</span>
            )}
          </div>
          <div className="flex-1 pb-2">
            <h1 className="text-4xl font-bold tracking-tight text-slate-900 mb-4">{employee.name}</h1>
            <div className="flex flex-wrap items-center gap-4">
              <span className="flex items-center gap-2 px-3 py-1.5 bg-teal-50 text-teal-600 rounded-lg border border-teal-100 text-[10px] font-bold uppercase tracking-wider shadow-sm">
                <BadgeInfo size={14} strokeWidth={2.5} /> {employee.id.slice(0, 8)}
              </span>
              <span className="flex items-center gap-2 px-3 py-1.5 bg-slate-50 text-slate-500 rounded-lg border border-slate-200 text-[10px] font-bold uppercase tracking-wider">
                <Clock size={14} strokeWidth={2.5} /> Joined {format(new Date(employee.joinDate), 'MMMM yyyy')}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Monthly Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        
        <div className="bg-white p-7 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between group hover:border-teal-400 transition-colors">
          <div className="flex items-start justify-between">
            <p className="text-[11px] font-bold uppercase tracking-widest text-slate-400">Monthly Presence</p>
            <UserCheck size={20} strokeWidth={2.5} className="text-teal-600" />
          </div>
          <div className="mt-8 flex items-baseline gap-2">
            <span className="text-4xl font-bold text-slate-900 tabular-nums">{monthlyAttendance.length}</span>
            <span className="text-sm font-bold text-slate-300">/ {daysInMonth.length} days</span>
          </div>
        </div>

        <div className="bg-white p-7 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between group hover:border-slate-400 transition-colors">
          <div className="flex items-start justify-between">
            <p className="text-[11px] font-bold uppercase tracking-widest text-slate-400">Total Absences</p>
            <BarChart3 size={20} strokeWidth={2.5} className="text-slate-400" />
          </div>
          <p className="text-4xl font-bold text-slate-900 mt-8 tabular-nums">{allTimeLeaves.length}</p>
        </div>

        <div className="bg-white p-7 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between group hover:border-amber-400 transition-colors">
          <div className="flex items-start justify-between">
            <p className="text-[11px] font-bold uppercase tracking-widest text-slate-400">Annual Leaves</p>
            <CalendarOff size={20} strokeWidth={2.5} className="text-amber-500" />
          </div>
          <div className="mt-8 flex flex-col gap-1">
            <div className="flex items-baseline gap-2">
              <span className="text-4xl font-bold text-slate-900 tabular-nums">{totalAnnual}</span>
              <span className="text-sm font-bold text-slate-300">/ {ANNUAL_LEAVE_LIMIT}</span>
            </div>
            <p className="text-[10px] font-bold uppercase tracking-widest text-amber-500 mt-1">{ANNUAL_LEAVE_LIMIT - totalAnnual} days remaining</p>
          </div>
        </div>

        <div className="bg-white p-7 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between group hover:border-rose-400 transition-colors">
          <div className="flex items-start justify-between">
            <p className="text-[11px] font-bold uppercase tracking-widest text-slate-400">Sick Leaves</p>
            <ShieldAlert size={20} strokeWidth={2.5} className="text-rose-500" />
          </div>
          <p className="text-4xl font-bold text-slate-900 mt-8 tabular-nums">{totalSick}</p>
        </div>
      </div>

      {/* Presence Matrix */}
      <div className="bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden">
        <div className="p-8 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-50/50">
          <div className="space-y-1 text-center sm:text-left">
             <h2 className="text-lg font-bold text-slate-800 tracking-tight">Presence Matrix</h2>
             <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Detailed historical activity log</p>
          </div>
          <div className="flex items-center gap-4 bg-white border border-slate-200 p-1.5 rounded-xl shadow-sm">
             <button 
                onClick={() => { const d = new Date(currentMonth); d.setMonth(d.getMonth() - 1); setCurrentMonth(d); }}
                className="p-2 hover:bg-slate-100 transition-all rounded-lg text-slate-400 hover:text-slate-900 focus:outline-none"
              >
               <ArrowLeft size={18} strokeWidth={2.5} />
             </button>
             <span className="font-bold uppercase tracking-wider text-[11px] text-slate-700 min-w-[120px] text-center">
               {format(currentMonth, 'MMMM yyyy')}
             </span>
             <button 
                onClick={() => { const d = new Date(currentMonth); d.setMonth(d.getMonth() + 1); setCurrentMonth(d); }}
                className="p-2 hover:bg-slate-100 transition-all rounded-lg text-slate-400 hover:text-slate-900 focus:outline-none rotate-180"
              >
               <ArrowLeft size={18} strokeWidth={2.5} />
             </button>
          </div>
        </div>

        <div className="p-8">
          <div className="grid grid-cols-7 gap-3 mb-6">
            {['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d => (
              <div key={d} className="text-center text-[10px] font-bold uppercase tracking-widest text-slate-300 py-2 border-b border-slate-50">{d}</div>
            ))}
          </div>
          
          <div className="grid grid-cols-7 gap-3">
            {Array.from({ length: monthStart.getDay() }).map((_, i) => (
              <div key={`empty-${i}`} className="h-32 rounded-xl bg-slate-50 border border-slate-100 opacity-40 shadow-inner" />
            ))}
            
            {daysInMonth.map((day) => {
              const dateStr = format(day, 'yyyy-MM-dd');
              const attRecord = attendance.find(a => a.employeeId === id && a.date === dateStr);
              const leaveRecord = allTimeLeaves.find(l => {
                const start = l.startDate;
                const end = l.endDate;
                return dateStr >= start && dateStr <= end;
              });
              const _isToday = isToday(day);

              return (
                <div 
                  key={dateStr} 
                  className={`h-32 rounded-xl border p-4 flex flex-col relative transition-all duration-300 ${
                    _isToday ? 'border-teal-600 bg-teal-50/20 shadow-md shadow-teal-100' : 'bg-white border-slate-100 hover:border-slate-200 hover:bg-slate-50 shadow-sm'
                  }`}
                >
                  <div className="flex justify-between items-start mb-auto">
                    <span className={`text-[11px] font-bold flex items-center justify-center w-7 h-7 rounded-lg transition-all ${
                      _isToday ? 'bg-teal-600 text-white' : 'text-slate-300'
                    }`}>
                      {format(day, 'd')}
                    </span>
                    {_isToday && <span className="text-[8px] font-bold uppercase tracking-widest text-teal-400">TODAY</span>}
                  </div>
                  
                  <div className="mt-4 space-y-2">
                    {leaveRecord ? (
                      <div className={`text-[9px] uppercase font-bold tracking-wider px-2 py-1.5 rounded-lg text-center border shadow-sm ${
                        leaveRecord.type === 'Annual' ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-slate-50 border-slate-200 text-slate-400'
                      }`}>
                        {leaveRecord.type === 'Annual' ? 'Annual' : 'Sick'}
                      </div>
                    ) : attRecord?.checkIn ? (
                      <div className="space-y-1.5">
                        <div className="bg-teal-600/5 text-teal-700 px-2 py-1 rounded-md border border-teal-100 flex items-center justify-between shadow-sm">
                          <span className="text-[8px] font-bold opacity-40 uppercase">IN</span>
                          <span className="text-[10px] font-bold tabular-nums">{attRecord.checkIn}</span>
                        </div>
                        {attRecord.checkOut && (
                          <div className="bg-slate-50 text-slate-400 px-2 py-1 rounded-md border border-slate-200 flex items-center justify-between">
                            <span className="text-[8px] font-bold opacity-40 uppercase">OUT</span>
                            <span className="text-[10px] font-bold tabular-nums">{attRecord.checkOut}</span>
                          </div>
                        )}
                      </div>
                    ) : null}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import { useState, useEffect } from "react";
import { Plus, Trash2, User, ChevronRight, Edit2 } from "lucide-react";
import Link from "next/link";
import { format } from "date-fns";

export default function EmployeesPage() {
  const [mounted, setMounted] = useState(false);
  const [isModalOpen, setModalOpen] = useState(false);
  const { employees, addEmployee, removeEmployee, updateEmployee } = useStore();

  const [name, setName] = useState("");
  const [photoUrl, setPhotoUrl] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => setMounted(true), []);

  if (!mounted) {
    return (
      <div className="animate-pulse space-y-8">
        <div className="h-10 w-64 bg-white border border-slate-200 rounded-xl" />
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3].map(i => <div key={i} className="h-64 bg-white border border-slate-200 rounded-2xl" />)}
        </div>
      </div>
    );
  }

  const openAddModal = () => {
    setName("");
    setPhotoUrl("");
    setEditingId(null);
    setModalOpen(true);
  };

  const openEditModal = (emp: { id: string; name: string; photoUrl?: string }) => {
    setName(emp.name);
    setPhotoUrl(emp.photoUrl || "");
    setEditingId(emp.id);
    setModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    if (editingId) {
      updateEmployee(editingId, { name: name.trim(), photoUrl: photoUrl.trim() });
    } else {
      addEmployee({ name: name.trim(), photoUrl: photoUrl.trim() });
    }

    setName("");
    setPhotoUrl("");
    setEditingId(null);
    setModalOpen(false);
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto pb-10">
      <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900">Employee Directory</h1>
          <p className="text-slate-500 mt-1 text-base">Manage personnel profiles and workforce information.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-teal-600 hover:bg-teal-700 text-white px-6 py-3 rounded-xl text-sm font-bold flex items-center gap-2.5 transition-all shadow-md shadow-teal-100"
        >
          <Plus size={18} strokeWidth={2.5}/> Add Employee
        </button>
      </header>

      {employees.length === 0 ? (
        <div className="bg-white border border-slate-200 rounded-2xl p-24 text-center flex flex-col items-center shadow-sm">
          <div className="w-20 h-20 bg-slate-50 text-slate-200 rounded-full flex items-center justify-center mb-6 border-2 border-slate-100 border-dashed">
            <User size={32} strokeWidth={2} />
          </div>
