"use client";

import { useStore } from "@/lib/store";
import { useEffect, useState } from "react";
import { format, isWithinInterval, parseISO } from "date-fns";
import { isBusinessDay } from "@/lib/dateUtils";
import { 
  Users, 
  UserCheck, 
  CalendarOff, 
  CalendarCheck,
  ArrowUpRight, 
  TrendingUp, 
  PieChart as PieChartIcon 
} from "lucide-react";
import Link from "next/link";
import AttendanceChart from "@/components/AttendanceChart";
import LeavePieChart from "@/components/LeavePieChart";
import MinimalDateSelector from "@/components/MinimalDateSelector";

export default function Dashboard() {
  const [mounted, setMounted] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [viewMode, setViewMode] = useState<"daily" | "whole_data">("daily");
  const { employees, attendance, leaves } = useStore();
  const selectedDateStr = format(selectedDate, 'yyyy-MM-dd');
  const isSelectedToday = format(selectedDate, 'yyyy-MM-dd') === format(new Date(), 'yyyy-MM-dd');

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <div className="animate-pulse space-y-8">
        <div className="h-40 bg-white border border-slate-200 rounded-xl" />
        <div className="flex gap-6">
          <div className="w-1/3 h-32 bg-white border border-slate-200 rounded-xl" />
        </div>
      </div>
    );
  }

  const isLeaveActive = (l: any, targetStr: string) => {
    if (!isBusinessDay(parseISO(targetStr))) return false;
    const start = l.startDate || l.date;
    const end = l.endDate || start;
    if (!start) return false;
    try { return isWithinInterval(parseISO(targetStr), { start: parseISO(start), end: parseISO(end) }); } catch { return false; }
  };

  const presentsOnSelectedDate = viewMode === "whole_data"
    ? attendance.filter(a => a.checkIn).length
    : attendance.filter(a => a.date === selectedDateStr && a.checkIn).length;
    
  const leavesOnSelectedDate = viewMode === "whole_data"
    ? leaves
    : leaves.filter(l => isLeaveActive(l, selectedDateStr));  

  const stats = [
    {
      label: "Total Personnel",
      value: employees.length,
      icon: Users,
      link: "/employees",
      color: "text-teal-600",
      bg: "bg-teal-50",
    },
    {
      label: viewMode === "whole_data" ? "Total Check-ins" : "Daily Presence",
      value: presentsOnSelectedDate,
      icon: UserCheck,
      link: "/attendance",
      color: "text-emerald-600",
      bg: "bg-emerald-50",
    },
    {
      label: viewMode === "whole_data" ? "Total Logged Leaves" : "Active Leaves",
      value: leavesOnSelectedDate.length,
      icon: CalendarOff,
      link: "/leaves",
      color: "text-rose-600",
      bg: "bg-rose-50",
    },
  ];

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto pb-10">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900">Dashboard</h1>
          <p className="text-slate-500 mt-1 text-base">Overview of core metrics and operational data.</p>
        </div>
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
          <div className="bg-white border border-slate-200 rounded-xl p-1 flex items-center shadow-sm">
            <button 
              onClick={() => setViewMode("daily")}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-lg transition-all ${viewMode === 'daily' ? 'bg-slate-100 text-slate-800 shadow-sm' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}
            >
              Daily View
            </button>
            <button 
              onClick={() => setViewMode("whole_data")}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-lg transition-all ${viewMode === 'whole_data' ? 'bg-slate-100 text-slate-800 shadow-sm' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}
            >
              Whole Data
            </button>
          </div>
          {viewMode === "daily" && (
            <MinimalDateSelector 
              selectedDate={selectedDate} 
              onDateChange={(date) => setSelectedDate(date)} 
            />
          )}
        </div>
      </header>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((stat) => {
          const Icon = stat.icon;
          return (
            <Link key={stat.label} href={stat.link} className="block group">
              <div className="relative p-7 bg-white border border-slate-200 rounded-2xl shadow-sm hover:shadow-md hover:border-slate-300 transition-all duration-300 overflow-hidden">
                <div className="relative flex items-center justify-between">
                  <div className="space-y-1">
                    <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">{stat.label}</p>
                    <p className="text-4xl font-bold text-slate-900 tracking-tight tabular-nums">{stat.value}</p>
                  </div>
                  <div className={`p-4 rounded-xl ${stat.bg} ${stat.color} shadow-sm group-hover:scale-105 transition-transform`}>
                    <Icon size={24} strokeWidth={2.5} />
                  </div>
                </div>
              </div>
            </Link>
          );
        })}
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center gap-2 mb-8">
            <TrendingUp size={18} className="text-teal-600" strokeWidth={2.5} />
            <h2 className="text-sm font-bold text-slate-800 tracking-tight">Attendance Analysis</h2>
          </div>
          <AttendanceChart selectedDate={selectedDate} viewMode={viewMode} />
        </div>

        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center gap-2 mb-8">
            <PieChartIcon size={18} className="text-rose-600" strokeWidth={2.5} />
            <h2 className="text-sm font-bold text-slate-800 tracking-tight">Leave Distribution</h2>
          </div>
          <LeavePieChart selectedDate={selectedDate} viewMode={viewMode} />
        </div>
      </div>

      {/* Lists Section */}
      <div className="grid grid-cols-1 gap-6">
        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-2">
              <CalendarCheck size={18} className="text-amber-500" strokeWidth={2.5} />
              <h2 className="text-sm font-bold text-slate-800 tracking-tight">
                {viewMode === "whole_data" ? "All Recorded Leaves" : `Active Entries ${isSelectedToday ? "Today" : `on ${format(selectedDate, 'MMM dd')}`}`}
              </h2>
            </div>
            <Link href="/leaves" className="text-[10px] font-bold text-teal-600 hover:text-teal-700 flex items-center gap-1.5 uppercase tracking-widest transition-colors">
              Manage Leaves <ArrowUpRight size={14} />
            </Link>
          </div>
          
          {leavesOnSelectedDate.length === 0 ? (
            <div className="text-center py-20 text-xs font-semibold text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
              No active entries found for this horizon.
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {leavesOnSelectedDate.map((leave) => {
                const emp = employees.find(e => e.id === leave.employeeId);
                return (
                  <div key={leave.id} className="flex items-center justify-between p-5 bg-slate-50 border border-slate-200 rounded-xl hover:bg-slate-100 transition-all group">
                    <div className="flex items-center gap-3.5">
                      <div className="w-10 h-10 rounded-full border-2 border-white bg-white shadow-sm flex items-center justify-center overflow-hidden">
                        {emp?.photoUrl ? (
                          <img src={emp.photoUrl} alt="avatar" className="w-full h-full object-cover" />
                        ) : (
                          <span className="text-sm font-bold text-slate-400 uppercase">{emp?.name.charAt(0)}</span>
                        )}
                      </div>
                      <span className="font-semibold text-sm text-slate-700 tracking-tight group-hover:text-slate-900">{emp?.name || 'Unknown'}</span>
                    </div>
                    <span className="px-3 py-1 text-[9px] font-bold tracking-wider uppercase border border-rose-200 bg-rose-50 text-rose-600 rounded-lg">
                      {leave.type}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import { useState, useEffect } from "react";
import { initializeApp, getApps, getApp, deleteApp } from "firebase/app";
import { getAuth, createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import { collection, onSnapshot, doc, setDoc, deleteDoc } from "firebase/firestore";
import { db, app } from "@/lib/firebase";
import { ShieldAlert, Trash2, UserPlus, Shield, Loader2 } from "lucide-react";

type SystemUser = {
  uid: string;
  name: string;
  email: string;
  role: string;
  createdAt: string;
};

export default function UsersPage() {
  const { user } = useStore();
  const [systemUsers, setSystemUsers] = useState<SystemUser[]>([]);
  const [mounted, setMounted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  useEffect(() => {
    setMounted(true);
    const unsub = onSnapshot(collection(db, "system_users"), (snapshot) => {
      setSystemUsers(snapshot.docs.map((d) => ({ uid: d.id, ...d.data() } as SystemUser)));
    });
    return () => unsub();
  }, []);

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    // Safely get or create the secondary app — avoids "already exists" error
    const secondaryApp = getApps().find(a => a.name === "SecondaryApp") 
      ? getApp("SecondaryApp") 
      : initializeApp(app.options, "SecondaryApp");

    try {
      // Use secondary app trick to create a user without signing out the current admin
      const secondaryAuth = getAuth(secondaryApp);

      const userCredential = await createUserWithEmailAndPassword(secondaryAuth, email, password);
      
      if (userCredential.user) {
        await updateProfile(userCredential.user, { displayName: name });
        // Save to firestore for listing
        await setDoc(doc(db, "system_users", userCredential.user.uid), {
          name,
          email,
          role: "admin",
          createdAt: new Date().toISOString()
        });
      }

      await secondaryAuth.signOut();
      
      setName("");
      setEmail("");
      setPassword("");
    } catch (err: any) {
      setError(err.message || "Failed to create user.");
    } finally {
      // Always clean up the secondary app instance to prevent stale references
      await deleteApp(secondaryApp).catch(() => {});
      setLoading(false);
    }
  };

  const handleDeleteUser = async (uid: string) => {
    if (!window.confirm("Remove this user? Notice: This deletes their database profile but cannot physically delete their Firebase Auth credential without an Admin SDK.")) return;
    
    try {
      await deleteDoc(doc(db, "system_users", uid));
    } catch (err: any) {
      alert("Error removing user: " + err.message);
    }
  };

  if (!mounted) return null;

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-5xl mx-auto pb-10">
      <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900">User Management</h1>
          <p className="text-slate-500 mt-1 text-base">Control access and system administrators.</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 border border-slate-200 bg-white rounded-2xl shadow-sm p-6">
          <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
            <UserPlus className="text-teal-600 w-5 h-5" />
            <h2 className="text-lg font-bold text-slate-800">Add New Admin</h2>
          </div>

          <form onSubmit={handleCreateUser} className="space-y-5">
            {error && (
              <div className="bg-rose-50 text-rose-600 p-3 rounded-lg text-xs flex items-center gap-2 border border-rose-100">
                <ShieldAlert size={14} className="shrink-0" />
                {error}
              </div>
            )}
            
            <div className="space-y-4">
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Name</label>
                <input required value={name} onChange={(e) => setName(e.target.value)} type="text" className="w-full px-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:border-teal-500 outline-none text-sm" placeholder="Jane Doe" />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Email</label>
                <input required value={email} onChange={(e) => setEmail(e.target.value)} type="email" className="w-full px-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:border-teal-500 outline-none text-sm" placeholder="jane@company.com" />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Password</label>
                <input required value={password} onChange={(e) => setPassword(e.target.value)} minLength={6} type="password" className="w-full px-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:border-teal-500 outline-none text-sm" placeholder="Min 6 characters" />
              </div>
            </div>

            <button disabled={loading} type="submit" className="w-full py-3 bg-teal-600 hover:bg-teal-700 text-white rounded-xl font-bold shadow-sm transition-all disabled:opacity-70 flex justify-center items-center gap-2 text-sm mt-6">
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Create Account"}
            </button>
          </form>
        </div>

        <div className="lg:col-span-2 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          {systemUsers.length === 0 ? (
            <div className="p-10 text-center text-slate-400 text-sm font-medium">
              No registered user profiles found.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-400 text-[11px] font-bold uppercase tracking-wider border-b border-slate-200">
                    <th className="px-6 py-4">User</th>
                    <th className="px-6 py-4">Email</th>
                    <th className="px-6 py-4">Role</th>
                    <th className="px-6 py-4">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {systemUsers.map((su) => (
                    <tr key={su.uid} className="hover:bg-slate-50 group transition-all duration-200">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-9 h-9 border-2 border-white bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-sm rounded-full shadow-sm">
                            {su.name.charAt(0)}
                          </div>
                          <span className="font-semibold text-sm text-slate-800">{su.name}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-sm font-medium text-slate-500">{su.email}</span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-teal-100 text-teal-700 text-[10px] font-bold uppercase tracking-wider rounded-md">
                          <Shield size={12} strokeWidth={3} /> {su.role}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {su.uid !== user?.uid && (
                          <button 
                            onClick={() => handleDeleteUser(su.uid)}
                            className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all"
                            title="Delete User"
                          >
                            <Trash2 size={16} strokeWidth={2.5} />
                          </button>
                        )}
                        {su.uid === user?.uid && (
                          <span className="text-[10px] uppercase font-bold text-slate-300">Current</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend
} from "recharts";
import { eachDayOfInterval, getYear } from "date-fns";
import { isBusinessDay, ANNUAL_LEAVE_LIMIT } from "@/lib/dateUtils";
import { BarChart3 } from "lucide-react";

interface Props {
  timeHorizon?: "current_year" | "all_time";
}

export default function AnnualLeaveChart({ timeHorizon = "current_year" }: Props) {
  const { employees, leaves } = useStore();
  const currentYear = new Date().getFullYear();

  const data = employees.map((emp) => {
    let taken = 0;

    // Filter to annual leaves for this employee
    const annualLeaves = leaves.filter(l => l.employeeId === emp.id && l.type === 'Annual');

    annualLeaves.forEach(l => {
      const start = new Date(l.startDate || (l as any).date || new Date());
      const end = new Date(l.endDate || (l as any).date || new Date());

      // Calculate intersection with current year
      try {
        const days = eachDayOfInterval({ start, end });
        days.forEach(d => {
          if ((timeHorizon === "all_time" || getYear(d) === currentYear) && isBusinessDay(d)) {
            taken += 1;
          }
        });
      } catch (e) {
        // Fallback for invalid dates
      }
    });

    return {
      name: emp.name.split(" ")[0], // Keep name short for X-axis
      taken: Math.min(taken, ANNUAL_LEAVE_LIMIT), // Cap visualization safely
      remaining: Math.max(0, ANNUAL_LEAVE_LIMIT - taken)
    };
  });

  if (data.length === 0) {
    return (
      <div className="flex flex-col h-[300px] items-center justify-center gap-3 text-[10px] font-bold text-slate-300 border-2 border-dashed border-slate-100 rounded-2xl uppercase tracking-[0.3em]">
        <BarChart3 size={24} className="opacity-40 mb-2" />
        No Employee Data
      </div>
    );
  }

  return (
    <div className="h-[350px] w-full bg-white p-7 rounded-2xl border border-slate-200 shadow-sm flex flex-col group hover:border-teal-400 transition-colors">
      <div className="flex items-start justify-between mb-8">
        <div>
          <h3 className="text-sm font-bold text-slate-800 tracking-tight">Annual Leave Distribution</h3>
          <p className="text-[11px] font-bold uppercase tracking-widest text-slate-400 mt-1">
             {timeHorizon === "all_time" ? "Whole Data (All Time)" : `Current Year (${currentYear})`} | {ANNUAL_LEAVE_LIMIT} Day Limit
          </p>
        </div>
        <BarChart3 size={20} strokeWidth={2.5} className="text-teal-600" />
      </div>

      <div className="flex-1 w-full min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data} margin={{ top: 0, right: 0, left: -25, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" vertical={false} />
            <XAxis 
              dataKey="name" 
              axisLine={false} 
              tickLine={false} 
              tick={{ fill: "#94A3B8", fontSize: 11, fontWeight: 700 }}
              dy={15}
            />
            <YAxis 
              domain={[0, ANNUAL_LEAVE_LIMIT]} 
              axisLine={false} 
              tickLine={false} 
              tick={{ fill: "#94A3B8", fontSize: 11, fontWeight: 700 }} 
            />
            <Tooltip
              cursor={{ fill: "rgba(13, 148, 136, 0.05)" }}
              contentStyle={{
                backgroundColor: "#FFFFFF",
                border: "1px solid #E2E8F0",
                borderRadius: "12px",
                color: "#0F172A",
                boxShadow: "0 8px 30px rgba(0,0,0,0.08)",
                fontSize: "12px",
                fontWeight: "700"
              }}
              itemStyle={{ fontWeight: "900", textTransform: "uppercase" }}
            />
            <Legend 
              verticalAlign="bottom" 
              height={30}
              iconType="circle"
              wrapperStyle={{ paddingTop: "20px", fontSize: "11px", fontWeight: "700", textTransform: "uppercase", letterSpacing: "1px", color: "#64748B" }}
            />
            <Bar dataKey="taken" name="Taken" stackId="a" fill="#0D9488" radius={[0, 0, 4, 4]} animationDuration={1000} />
            <Bar dataKey="remaining" name="Remaining" stackId="a" fill="#E2E8F0" radius={[4, 4, 0, 0]} animationDuration={1000} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

