"use client";

import { useStore } from "@/lib/store";
import { eachDayOfInterval, getYear } from "date-fns";
import { isBusinessDay, ANNUAL_LEAVE_LIMIT } from "@/lib/dateUtils";
import { CalendarOff, BadgeAlert } from "lucide-react";

interface Props {
  timeHorizon?: "current_year" | "all_time";
}

export default function LeaveBalancesGrid({ timeHorizon = "current_year" }: Props) {
  const { employees, leaves } = useStore();
  const currentYear = new Date().getFullYear();

  const data = employees.map((emp) => {
    let annualTaken = 0;
    let sickTaken = 0;

    // Process leaves specific to employee
    const empLeaves = leaves.filter(l => l.employeeId === emp.id);

    empLeaves.forEach(l => {
      const start = new Date(l.startDate || (l as any).date || new Date());
      const end = new Date(l.endDate || (l as any).date || new Date());

      try {
        const days = eachDayOfInterval({ start, end });
        days.forEach(d => {
          if ((timeHorizon === "all_time" || getYear(d) === currentYear) && isBusinessDay(d)) {
            if (l.type === 'Annual') annualTaken += 1;
            else sickTaken += 1;
          }
        });
      } catch (e) {
        // Safe fallback in case of invalid dates
      }
    });

    return {
      emp,
      annualTaken: Math.min(annualTaken, ANNUAL_LEAVE_LIMIT), // Safe limit bounds
      sickTaken
    };
  });

  if (data.length === 0) return null;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 w-full mt-2">
      {data.map((item) => {
        const { emp, annualTaken, sickTaken } = item;
        const remaining = Math.max(0, ANNUAL_LEAVE_LIMIT - annualTaken);
        const percent = (annualTaken / ANNUAL_LEAVE_LIMIT) * 100;

        return (
          <div key={emp.id} className="bg-white border border-slate-200 rounded-2xl shadow-sm hover:shadow-md hover:border-teal-300 transition-all overflow-hidden group flex flex-col">
            <div className="p-6 py-5 border-b border-slate-50 flex items-center gap-4 shrink-0 bg-white">
               <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center font-bold text-slate-300 border border-slate-100 shadow-inner overflow-hidden uppercase shrink-0">
                 {emp.photoUrl ? <img src={emp.photoUrl} alt="" className="w-full h-full object-cover" /> : emp.name.charAt(0)}
               </div>
               <div className="overflow-hidden">
                 <h3 className="font-bold text-slate-800 tracking-tight truncate">{emp.name}</h3>
                 <span className="text-[10px] uppercase font-bold tracking-widest text-slate-400 block truncate">{emp.id.slice(0, 8)}</span>
               </div>
            </div>

            <div className="p-6 bg-slate-50/50 space-y-6 flex-1 flex flex-col justify-between">

              {/* Annual Leave Details */}
              <div>
                <div className="flex justify-between items-end mb-3">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
                    <CalendarOff size={14} className="text-amber-500" />
                    Annual Usage
                  </span>
                  <div className="text-right">
                    <span className="font-bold text-slate-900 text-sm">{annualTaken}</span>
                    <span className="text-xs font-bold text-slate-400"> / {ANNUAL_LEAVE_LIMIT}</span>
                  </div>
                </div>
                {/* Advanced Progress Visualizer */}
                <div className="h-2 w-full bg-slate-200/60 rounded-full overflow-hidden flex shadow-inner">
                   <div 
                     className="h-full bg-teal-600 rounded-full transition-all duration-1000 ease-out shadow-sm" 
                     style={{ width: `${percent}%` }}
                   />
                </div>
                <div className="mt-2.5 text-right">
                   <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                     <span className="text-teal-600">{remaining} Days</span> Remaining
                   </span>
                </div>
              </div>

              {/* Sick Leaves Details */}
              <div className="flex items-center justify-between pt-5 border-t border-slate-100">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
                    <BadgeAlert size={14} className="text-rose-500" />
                    Sick Log
                  </span>
                  <span className="font-bold text-slate-900 text-sm flex items-center gap-1.5 tabular-nums">
                    {sickTaken} <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mt-0.5">Days</span>
                  </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useStore } from "@/lib/store";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from "recharts";

import { isSameMonth } from "date-fns";
import { PieChart as PieChartIcon } from "lucide-react";

interface LeavePieChartProps {
  selectedDate?: Date;
  viewMode?: "daily" | "whole_data";
}

export default function LeavePieChart({ selectedDate = new Date(), viewMode = "daily" }: LeavePieChartProps) {
  const { leaves } = useStore();

  const normalize = (l: any) => ({
    ...l,
    startDate: l.startDate || l.date || new Date().toISOString(),
    endDate: l.endDate || l.date || new Date().toISOString(),
  });

  const normalizedLeaves = leaves.map(normalize);
  const filteredLeaves = viewMode === "whole_data" 
    ? normalizedLeaves 
    : normalizedLeaves.filter((l) => isSameMonth(new Date(l.startDate), selectedDate) || isSameMonth(new Date(l.endDate), selectedDate));
  
  let annualCount = 0;
  let sickCount = 0;

  filteredLeaves.forEach(l => {
    const diffTime = Math.abs(new Date(l.endDate).getTime() - new Date(l.startDate).getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
    if (l.type === "Annual") annualCount += diffDays;
    else sickCount += diffDays;
  });

  const data = [
    { name: "Annual", value: annualCount, color: "#0D9488" }, 
    { name: "Sick/Emergency", value: sickCount, color: "#E11D48" }, 
  ];

  if (annualCount === 0 && sickCount === 0) {
    return (
      <div className="flex flex-col h-[300px] items-center justify-center gap-3 text-[10px] font-bold text-slate-300 border-2 border-dashed border-slate-100 rounded-2xl uppercase tracking-[0.3em]">
        <PieChartIcon size={24} className="opacity-40 mb-2" />
        No Leave Data
      </div>
    );
  }

  return (
    <div className="h-[300px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={65}
            outerRadius={85}
            paddingAngle={8}
            dataKey="value"
            animationDuration={1500}
          >
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} stroke="#000000" strokeWidth={2} className="hover:opacity-80 transition-opacity" />
            ))}
          </Pie>
          <Tooltip
            contentStyle={{
              backgroundColor: "#FFFFFF",
              border: "1px solid #E2E8F0",
              borderRadius: "12px",
              color: "#0F172A",
              boxShadow: "0 8px 30px rgba(0,0,0,0.08)",
              fontSize: "12px",
              fontWeight: "700"
            }}
            itemStyle={{ fontWeight: "900", textTransform: 'uppercase' }}
          />
          <Legend
            verticalAlign="bottom"
            height={36}
            iconType="circle"
            formatter={(value) => (
              <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em]">
                {value}
              </span>
            )}
          />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}

import { isWeekend, eachDayOfInterval } from "date-fns";

/**
 * Checks if a date is a business day (Monday - Friday).
 */
export const isBusinessDay = (date: Date): boolean => {
  return !isWeekend(date);
};

/**
 * Returns an array of dates within the interval that are business days.
 */
export const getBusinessDaysInInterval = (start: Date, end: Date): Date[] => {
  try {
    const allDays = eachDayOfInterval({ start, end });
    return allDays.filter(isBusinessDay);
  } catch (error) {
    console.error("Invalid interval for getBusinessDaysInInterval", { start, end });
    return [];
  }
};

